class Solution {
public:
    bool closeStrings(string word1, string word2) {
        map<char, int> a, b;
        for (char c : word1) a[c]++;
        for (char c : word2) b[c]++;
        vector<int> ca, cb;
        for (auto& [c, n] : a) {
            if (!b.count(c)) return false;
            ca.push_back(n);
        }
        for (auto& [c, n] : b) {
            if (!a.count(c)) return false;
            cb.push_back(n);
        }
        sort(ca.begin(), ca.end());
        sort(cb.begin(), cb.end());
        return ca == cb;
    }
};
